<script setup lang="ts">
import { onMounted, ref } from "vue"; import { useRouter } from "vue-router"; import { api } from "../lib/request"; import { setTenant } from "../composables/useAuth";
const router=useRouter(); const items=ref<any[]>([]), name=ref(""), error=ref(""); async function load(){try{items.value=(await api<any>("/api/v1/tenants")).items}catch(e:any){error.value=e.message}} async function create(){try{const tenant=await api<any>("/api/v1/tenants",{method:"POST",body:JSON.stringify({name:name.value})});name.value="";setTenant(tenant.id);await router.push("/")}catch(e:any){error.value=e.message}} async function toggle(item:any){await api(`/api/v1/tenants/${item.id}`,{method:"PATCH",body:JSON.stringify({status:item.status==="active"?"disabled":"active"})});await load()} onMounted(load);
</script>
<template><section><h2>租户管理</h2><el-alert v-if="error" :title="error" type="error"/><el-form inline @submit.prevent="create"><el-form-item label="租户名称"><el-input v-model="name"/></el-form-item><el-button type="primary" native-type="submit">创建租户</el-button></el-form><el-table :data="items"><el-table-column prop="name" label="名称"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button link @click="toggle(s.row)">{{s.row.status==='active'?'停用':'启用'}}</el-button></template></el-table-column></el-table></section></template>
